/**
 * 刷出入库缓冲（文件队列）
 *
 * 由 Schedule Trigger 定时触发：读取缓冲目录，按「剧名+季」分组，
 * 满足「最后一条到达后静默满 TRANSFER_IDLE_SECONDS 秒」或「首条等待达 TRANSFER_MAX_WAIT_SECONDS 秒」
 * 即交给「合并入库通知」。
 *
 * 安全机制：
 * - 用 renameSync 原子抢占为 .processing，避免并发双发；
 * - 不在此节点提前删除 .processing，而是把路径交给「合并入库通知」构造成功后清理；
 * - 若下游意外中断导致 .processing 滞留超过 RECOVERY_SECONDS，自动恢复回 .json 重试一次。
 */

const BUFFER_DIR = "/home/node/.n8n/transfer_buffer"; // 与「入库缓冲」保持一致
const TRANSFER_IDLE_SECONDS = 20; // 最后一集到达后静默 20 秒再合并（避免连续入库被腰斩）
const TRANSFER_MAX_WAIT_SECONDS = 120; // 首集到达后最长等待 120 秒兜底必发
const RECOVERY_SECONDS = 300; // .processing 滞留 5 分钟视为异常中断，自动恢复重试一次
const STALE_SECONDS = 3600; // 清理超过 1 小时的残留 .tmp 或二次失败的 .processing

let fs = null;
try {
    fs = require("fs");
} catch (e) {
    fs = null;
}
if (!fs) return [];

const now = Date.now();

// 先检查是否有因异常中断遗留的 .processing 文件：首次滞留恢复为 .recovered.json 重试一次
try {
    for (const name of fs.readdirSync(BUFFER_DIR)) {
        const full = `${BUFFER_DIR}/${name}`;
        if (name.endsWith(".processing")) {
            try {
                const age = now - fs.statSync(full).mtimeMs;
                if (age > RECOVERY_SECONDS * 1000 && !name.includes(".recovered.")) {
                    const recovered = full.replace(/\.json\.processing$/, ".recovered.json");
                    fs.renameSync(full, recovered);
                } else if (age > STALE_SECONDS * 1000) {
                    fs.unlinkSync(full);
                }
            } catch (e) {
                // 忽略并发竞争
            }
        } else if (name.endsWith(".tmp")) {
            try {
                if (now - fs.statSync(full).mtimeMs > STALE_SECONDS * 1000) fs.unlinkSync(full);
            } catch (e) {
                // 忽略
            }
        }
    }
} catch (e) {
    return [];
}

let files = [];
try {
    files = fs.readdirSync(BUFFER_DIR).filter((name) => name.endsWith(".json"));
} catch (e) {
    return [];
}

const records = [];
for (const file of files) {
    try {
        const data = JSON.parse(fs.readFileSync(`${BUFFER_DIR}/${file}`, "utf8"));
        records.push({
            file,
            at: Number(data.at) || 0,
            transfer: data.transfer || {},
            bark: data.bark
        });
    } catch (e) {
        // 跳过损坏/写了一半的文件
    }
}

const groups = new Map();
for (const record of records) {
    const transfer = record.transfer;
    if (!transfer || transfer.kind !== "episode" || !record.bark) continue;
    const key = `${transfer.show}|S${transfer.season}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(record);
}

const out = [];
for (const list of groups.values()) {
    const times = list.map((record) => record.at || now);
    const firstAt = Math.min(...times);
    const lastAt = Math.max(...times);
    const idleReady = now - lastAt >= TRANSFER_IDLE_SECONDS * 1000;
    const maxWaitReady = now - firstAt >= TRANSFER_MAX_WAIT_SECONDS * 1000;
    if (!idleReady && !maxWaitReady) continue;

    // rename 抢占文件，避免两个刷出执行同时发送同一批
    const claimed = [];
    for (const record of list) {
        const source = `${BUFFER_DIR}/${record.file}`;
        const target = `${source}.processing`;
        try {
            fs.renameSync(source, target);
            claimed.push({ ...record, target });
        } catch (e) {
            // 已被其它执行处理
        }
    }
    if (!claimed.length) continue;

    out.push({
        json: {
            claimedFiles: claimed.map((record) => record.target),
            items: claimed.map((record) => ({
                episode: record.transfer.episode,
                episodes: Array.isArray(record.transfer.episodes) && record.transfer.episodes.length
                    ? record.transfer.episodes
                    : [record.transfer.episode],
                size: record.transfer.size,
                bark: record.bark,
                meta: record.transfer
            }))
        }
    });
}

return out;
